const uint N = rows * I;
const uint base = thread_position_in_grid.x * 8;
if (base >= N) return;
if (base + 8 <= N) {
    uint4 ga = ld16(g + base);
    uint4 ua = ld16(u + base);
    float4 a0 = float4(as_type<half4>(ga.xy)), a1 = float4(as_type<half4>(ga.zw));
    float4 b0 = float4(as_type<half4>(ua.xy)), b1 = float4(as_type<half4>(ua.zw));
    float4 r0 = swg(a0, b0), r1 = swg(a1, b1);
    uint4 o;
    o.xy = as_type<uint2>(half4(r0));
    o.zw = as_type<uint2>(half4(r1));
    st16(out + base, o);
} else {
    for (uint i = base; i < N; ++i) {
        float a = float(g[i]);
        out[i] = half(a / (1.0f + metal::fast::exp2(-a * 1.4426950408889634f)) * float(u[i]));
    }
}

