inline uint4 ld16(const device half* p) { return *(const device uint4*)p; }
inline uint4 ld16(const constant half* p) { return *(const constant uint4*)p; }
inline void st16(device half* p, uint4 v) { *(device uint4*)p = v; }
inline float4 swg(float4 a, float4 b) { return a / (1.0f + metal::fast::exp2(a * -1.4426950408889634f)) * b; }
